int b1=2, b2=3, led=13, buzzer=8;
void setup(){pinMode(b1,INPUT);pinMode(b2,INPUT);pinMode(led,OUTPUT);pinMode(buzzer,OUTPUT);Serial.begin(9600);}
void loop(){
  int w=0;
  if(digitalRead(b1)==HIGH) w=1;
  else if(digitalRead(b2)==HIGH) w=2;
  if(w>0){                          // kim birinchi bosdi
    Serial.print("BTN:");Serial.println(w);
    digitalWrite(led,HIGH); tone(buzzer,1200,40); delay(250);
    digitalWrite(led,LOW); Serial.println("BTN:0");
  }
  delay(12);
}
